{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks server-side encryption",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled, which could lead to sensitive data being stored unencrypted at rest."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
}",
  "fix_summary": "Added server-side encryption configuration to the S3 bucket to ensure data is encrypted at rest using AES256."
}
